namespace NovaHarvest.Core.NPC; public sealed class NPCRelationship { public int Friendship{get;private set;} public int MaxFriendship{get;}=100; public bool IsTrusted=>Friendship>=60;public bool IsCloseFriend=>Friendship>=90; public void IncreaseFriendship(int n){if(n>0)Friendship=Math.Min(MaxFriendship,Friendship+n);} public void DecreaseFriendship(int n){if(n>0)Friendship=Math.Max(0,Friendship-n);} }
